CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261124230049_InitialPostgreSqlSchema') THEN
    CREATE TABLE "Churches" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(100) NOT NULL,
        "Denomination" character varying(100),
        "Email" character varying(254) NOT NULL,
        "PasswordHash" character varying(512),
        "Phone" character varying(40) NOT NULL DEFAULT '',
        "Address" character varying(250) NOT NULL DEFAULT '',
        "LogoUrl" character varying(500),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
        CONSTRAINT "PK_Churches" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
